import{_ as t,o as i,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.4.8 View Agency Invitation Status","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-8-view-agency-invitation-status/spec.md","filePath":"feature/agency-workspace/3-4-8-view-agency-invitation-status/spec.md"}'),s={name:"feature/agency-workspace/3-4-8-view-agency-invitation-status/spec.md"};function o(r,e,l,d,c,h){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-4-8-view-agency-invitation-status" tabindex="-1">3.4.8 View Agency Invitation Status <a class="header-anchor" href="#_3-4-8-view-agency-invitation-status" aria-label="Permalink to &quot;3.4.8 View Agency Invitation Status&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>An Owner opens the pending-invitation tab of an Agency to review, cancel or follow up its invitations; or an invited person opens their own pending invitations to see what is still open and to accept or decline.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Agency Owner (invitations of their Agency) and invited person (their own invitations).</li><li><strong>Purpose:</strong> Let both sides see where an invitation stands, so they know whether it is still open, has lapsed, has been accepted or has been withdrawn.</li><li><strong>Interface:</strong> For the Owner, a pending-invitation tab in the Member list of the Agency (<code>/agencies/:agencyId/members</code>), listing every invitation with its status and a cancel action on the open ones. For the invited person, a &quot;My invitations&quot; section listing the invitations still valid, each with an accept and a decline action.</li><li><strong>Data Processing:</strong> The system returns the invitations of an Agency for its Owner, deriving the lapsed ones at read time, and returns the still-valid invitations addressed to the signed-in email for an invited person. Cancelling an open invitation withdraws it, and declining an invitation does the same from the invited person&#39;s side.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Invitation list:</p><ul><li>Owner view: one row per invitation with the invited email, the pre-assigned Workspace and role if any, the expiry time, the derived status and a cancel action on the open ones.</li><li>Invited person view: one row per still-valid invitation with the Agency name, the expiry time, an accept action and a decline action.</li><li>Statuses shown as badges: PENDING, EXPIRED, ACCEPTED, REVOKED.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> For the Owner view, the Agency identifier (<code>agencyId</code>); for the invited-person view, the signed-in session. Cancelling needs the invitation identifier; declining needs the invitation token.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The invitations of the Agency — id, agencyId, agencyName, invitedEmail, invitedBy, token, note, workspaceId, workspaceName, role (nullable), status (InvitationStatus: PENDING, ACCEPTED, EXPIRED, REVOKED), expiresAt, acceptedAt (nullable), createdAt (full field list at 3.4.7) — and the email of the signed-in user.</li><li><strong>Output:</strong> For the Owner, every invitation of the Agency whatever its status, with lapsed ones shown as expired. For the invited person, only the invitations addressed to their email that are still open. Cancelling and declining return no data.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-27:</strong> Only the Owner of the Agency may list or cancel its invitations, per the same Invite rule (BR-27, &quot;only OWNER/MANAGER&quot; adapted to the Agency&#39;s single-Owner model). Anybody else is refused with <code>403 NOT_AGENCY_OWNER</code>.</li><li>An invitation is valid for the period set when it was sent — 30 days by default, settable between 1 and 30 days (BR-27, 3.4.7). <ul><li><strong>⚠ BA conflict (needs team decision):</strong> see the same note in <code>3-4-7-invite-agency-member/spec.md</code> — <code>docs/ba/03-agency-workspace-management.md</code> states a fixed 3-day expiry, while the code implements 30 days adjustable 1–30. Not yet reconciled.</li></ul></li><li>Expiry is derived when the list is read, not by a scheduled job: after the expiry time passes the stored record keeps its PENDING status, and the system reports it as EXPIRED without writing that back to storage. Two reads taken either side of the expiry time may therefore report different statuses for the same record.</li><li>The Owner sees lapsed invitations reported as expired. The invited person does not: their list drops anything that is no longer PENDING or has passed its expiry time, so it holds valid invitations only.</li><li>The Owner may cancel an invitation while it is still PENDING, which moves it to REVOKED. An invitation that has already been accepted, lapsed or withdrawn cannot be cancelled.</li><li>The invited person may decline an invitation with its token, which also moves it to REVOKED — the status model has no separate value for a declined invitation.</li><li>There is no renewal or resend of an existing invitation. Sending a new invitation is the way forward, and the old one can only be withdrawn.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller is not the Agency Owner → Display: MSG39</li><li>The invitation does not exist, or does not belong to the Agency → Display: MSG38</li><li>Cancelling an invitation that is no longer PENDING → Display: MSG38 (closest fit — no dedicated MSG code for an invalid-state invitation)</li><li>Accepting an invitation that is not PENDING or has passed its expiry time → Display: MSG38 (closest fit — no dedicated MSG code for an expired/invalid invitation)</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Owner opens the pending-invitation tab of an Agency.</li><li>The client requests the invitations of the Agency with the signed-in session.</li><li>The system confirms the caller is the Owner of the Agency.</li><li>The system reads every invitation of the Agency and reports the lapsed ones as EXPIRED at read time, without writing the change back.</li><li>The client renders the list with the reported statuses.</li><li>The invited person opens their own invitation list.</li><li>The system returns the invitations addressed to the signed-in email that are still PENDING and unexpired.</li><li>The client renders them with an accept and a decline action on each.</li><li>When the Owner selects cancel on an open invitation, the system moves it to REVOKED and the client drops the row; toast MSG36 (closest fit — reused from &quot;member removed&quot;; no dedicated MSG code for a cancelled invitation).</li><li>When the invited person selects decline, the system moves the invitation to REVOKED and the client drops the row.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Caller is not the Agency Owner (BR-27) → <code>403 NOT_AGENCY_OWNER</code>, toast MSG39; no list is returned. 3.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>9.a1: Cancelling an invitation that does not exist or belongs to another Agency → <code>404 INVITATION_NOT_FOUND</code>, toast MSG38. 9.a2: The Owner refreshes the invitation list.</li><li>9.b1: Cancelling an invitation that has already been accepted, lapsed or withdrawn → <code>400 INVALID_INVITATION</code>, toast MSG38 (closest fit). 9.b2: The Owner refreshes the list to see its current status.</li><li>10.a1: The invitation lapses exactly as the invited person accepts it → the system re-checks the PENDING status and the expiry time at acceptance and refuses with <code>400 INVALID_INVITATION</code>, toast MSG38 (closest fit); creating no Agency membership. 10.a2: The invited person asks the Owner to send a new invitation.</li><li>4.a1: Because expiry is derived at read time, two reads taken either side of the expiry time may report different statuses for the same stored record — this is the intended behaviour, not an error; no toast. 4.a2: The user re-reads the list if the status looks stale.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The Owner sees every invitation of the Agency with its current status, lapsed ones included.</li><li>The invited person sees only the invitations that are still valid for their email.</li><li>After a cancel or a decline, the invitation carries the REVOKED status.</li><li>No Agency membership is created while an invitation is not accepted.</li></ul>',22)])])}const v=t(s,[["render",o]]);export{p as __pageData,v as default};
